import React from 'react';
import './css/Emaillist.css';

export interface Email {
    id: number;
    sender: string;
    subject: string;
    body: string;
    date: string;
    avatarUrL: string;
    isRead: boolean;
    folder
}

export interface EmailListProps {
    email: Email[];
    onSelectEmail: (id: number) => void;
    selectedEmailid: number | null;
}

export const EmailList: React.FC<EmailListProps> = ({
    email, onSelectEmail, selectedEmailid,
}) => {
    const formatDate = (datestring: string): string => {
        const options: Intl.DateTimeFormatOptions = {
            year: 'numeric',
            month: 'short',
            day: 'numeric',
            hour: '2-digit',
            minute: '2-digit',
        };
        return new Date(datestring).toLocaleDateString(undefined, options);
    };


    return (
        <div className="email-list">
            {email.map((email) => (
                <button
                    key={email.id}
                    onClick={() => onSelectEmail(email.id)} className={`email-item ${selectedEmailid === email.id ? 'email-item--selected' : ''}`}
                    aria-current={selectedEmailid === email.id ? 'true' : 'false'}>
                    <img
                        src={email.avatarUrL} alt={`Avatar of ${email.sender}`} className="email-avatar" />
                    <div className="email-content">
                        <div className="email-header">
                            <p className={`email-sender ${email.isRead ? 'read' : 'unread'}`}> {email.sender} </p>
                            <p className="email-date">{formatDate(email.date)}</p>
                        </div>
                        <p className={`email-subject ${email.isRead ? 'read' : 'unread'}`}>
                            {email.subject}
                        </p>
                    </div>
                </button>
            ))}
        </div>
    );
};
